<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage } from "element-plus";
import { workflowApi, type Workflow, type WorkflowExecution, type WorkflowTrigger, type SchedulerStatus, type WorkflowVersion, type ScheduledMisfirePolicy, type OperatorActionAvailability, type OperatorActionName } from "@/api/workflows";
import PageHeader from "@/components/ui/PageHeader.vue";
import SurfaceCard from "@/components/ui/SurfaceCard.vue";
import StatePanel from "@/components/ui/StatePanel.vue";
import ConfirmDialog from "@/components/ui/ConfirmDialog.vue";

type PageState = "loading" | "empty" | "error" | "permission" | "success";
type ExecutionAction = "run" | "cancel" | "retry" | "resume";
type TriggerAction = "invoke" | "enable" | "disable" | "delete";
type DiagnosticFocus = "trace" | "audit";
type TriggerEditor = { trigger: WorkflowTrigger | null; name: string; timezone: string; interval_seconds: number; misfire_policy: ScheduledMisfirePolicy; catch_up_limit: number; event_id_field: string; secret: string };
const route = useRoute(); const router = useRouter();
const workflows = ref<Workflow[]>([]); const versions = ref<WorkflowVersion[]>([]); const triggers = ref<WorkflowTrigger[]>([]); const schedules = ref<Record<string, SchedulerStatus>>({}); const executions = ref<WorkflowExecution[]>([]);
const executionAvailability = ref<Record<string, OperatorActionAvailability[]>>({}); const triggerAvailability = ref<Record<string, OperatorActionAvailability[]>>({});
const selectedId = ref(typeof route.query.workflow_id === "string" ? route.query.workflow_id : ""); const focusedExecutionId = ref(typeof route.query.execution_id === "string" ? route.query.execution_id : ""); const diagnosticTraceId = ref(typeof route.query.trace_id === "string" ? route.query.trace_id : ""); const diagnosticAuditId = ref(typeof route.query.audit_id === "string" ? route.query.audit_id : "");
const loading = ref(false); const detailLoading = ref(false); const error = ref(""); const detailError = ref(""); const permissionDenied = ref(false); const pageState = ref<PageState>("loading");
const invokeDialogVisible = ref(false); const invokeLoading = ref(false); const invokeTarget = ref<WorkflowTrigger | null>(null); const executionDialogVisible = ref(false); const executionActionLoading = ref(false); const executionAction = ref<ExecutionAction | null>(null); const executionTarget = ref<WorkflowExecution | null>(null);
const triggerEditorVisible = ref(false); const triggerEditorLoading = ref(false); const triggerEditor = ref<TriggerEditor>({ trigger: null, name: "", timezone: "UTC", interval_seconds: 300, misfire_policy: "skip", catch_up_limit: 10, event_id_field: "event_id", secret: "" });
const deleteTriggerDialogVisible = ref(false); const deleteTriggerLoading = ref(false); const deleteTriggerTarget = ref<WorkflowTrigger | null>(null); const triggerActionDialogVisible = ref(false); const triggerActionLoading = ref(false); const triggerAction = ref<Exclude<TriggerAction, "invoke" | "delete"> | null>(null); const triggerActionTarget = ref<WorkflowTrigger | null>(null);
const selected = computed(() => workflows.value.find((item) => item.id === selectedId.value)); const publishedVersion = computed(() => versions.value.find((item) => item.id === selected.value?.published_version_id)); const focusedExecution = computed(() => executions.value.find((item) => item.id === focusedExecutionId.value));
const diagnosticFocus = computed<DiagnosticFocus | null>(() => diagnosticTraceId.value ? "trace" : diagnosticAuditId.value ? "audit" : null); const diagnosticFocusId = computed(() => diagnosticTraceId.value || diagnosticAuditId.value); const diagnosticFocusLabel = computed(() => diagnosticFocus.value === "trace" ? "Trace ID" : diagnosticFocus.value === "audit" ? "Audit ID" : "诊断上下文");
const stateTitle = computed(() => ({ loading: "正在加载工作流", empty: "暂无工作流", permission: "无权查看工作流", error: "工作流加载失败" } as Record<string,string>)[pageState.value] ?? "工作流"); const stateDescription = computed(() => ({ loading: "正在同步工作流生命周期数据。", empty: "当前没有可用工作流，请先创建工作流。", permission: "当前账号没有工作流访问权限，请联系管理员。", error: "无法同步工作流数据，请检查服务状态后重试。" } as Record<string,string>)[pageState.value] ?? "");
const lifecycleSteps = computed(() => [{ label:"工作流", done:Boolean(selected.value), active:false },{ label:"版本", done:Boolean(publishedVersion.value), active:Boolean(selected.value)&&!publishedVersion.value },{ label:"发布", done:selected.value?.status === "published", active:Boolean(publishedVersion.value)&&selected.value?.status !== "published" },{ label:"触发器", done:triggers.value.length>0, active:selected.value?.status === "published"&&triggers.value.length===0 },{ label:"运行", done:executions.value.length>0, active:selected.value?.status === "published"&&executions.value.length===0 }]);
const statusText: Record<string,string> = { draft:"草稿", published:"已发布", archived:"已归档", pending:"等待中", running:"运行中", completed:"已完成", failed:"失败", cancelled:"已取消", retrying:"重试中", skipped:"已跳过", enabled:"已启用", disabled:"已停用" }; const triggerTypeText: Record<string,string> = { manual:"手动", scheduled:"定时", webhook:"Webhook" }; const actionText: Record<ExecutionAction,string> = { run:"运行", cancel:"取消", retry:"重试", resume:"恢复" }; const triggerActionText: Record<TriggerAction,string> = { invoke:"立即运行", enable:"启用", disable:"停用", delete:"删除" };
const displayStatus = (v?:string) => v ? statusText[v] || `未知状态（${v}）` : "-"; const displayTriggerType = (v?:string) => v ? triggerTypeText[v] || `未知类型（${v}）` : "-"; const displayTriggerAction = (a:OperatorActionName) => triggerActionText[a as TriggerAction] || a; const formatTime = (v?:string|null) => v ? new Date(v).toLocaleString("zh-CN",{hour12:false}) : "-";
const asExecution = (r:unknown) => r as WorkflowExecution; const asTrigger = (r:unknown) => r as WorkflowTrigger;
function executionActions(e:WorkflowExecution) { return (executionAvailability.value[e.id]||[]).filter((x)=>["run","cancel","retry","resume"].includes(x.action)&&x.allowed).map((x)=>x.action as ExecutionAction); } function executionActionAvailability(e:WorkflowExecution,a:ExecutionAction){return executionAvailability.value[e.id]?.find(x=>x.action===a);} function triggerActionAvailability(t:WorkflowTrigger,a:TriggerAction){return triggerAvailability.value[t.id]?.find(x=>x.action===a);} function triggerActionAllowed(t:WorkflowTrigger,a:TriggerAction){return triggerActionAvailability(t,a)?.allowed===true;} function triggerActionReason(t:WorkflowTrigger,a:TriggerAction){return triggerActionAvailability(t,a)?.reason_code||"ACTION_NOT_AVAILABLE";}
function lifecycleQuery(executionId?:string){return {...(selected.value?{workflow_id:selected.value.id}:{}),...(executionId?{execution_id:executionId}:{}),source:"workflow-lifecycle"};} function focusExecution(e:WorkflowExecution){focusedExecutionId.value=e.id;diagnosticTraceId.value="";diagnosticAuditId.value="";void router.replace({path:"/workflows/lifecycle",query:lifecycleQuery(e.id)});} function openRuntimeExecution(e:WorkflowExecution){focusedExecutionId.value=e.id;void router.push({path:"/runtime",query:{tab:"executions",source:"workflow-lifecycle",execution_id:e.id,workflow_id:e.workflow_id,workflow_version_id:e.workflow_version_id}});} function openRuntimeCorrelations(e:WorkflowExecution,focus?:DiagnosticFocus,focusId?:string){focusedExecutionId.value=e.id;void router.push({path:"/runtime",query:{tab:"correlations",source:"workflow-lifecycle",focus_type:focus??"execution",focus_id:focusId??e.id,execution_id:e.id,workflow_id:e.workflow_id,workflow_version_id:e.workflow_version_id}});} function continueDiagnostic(){if(focusedExecution.value&&diagnosticFocus.value&&diagnosticFocusId.value)openRuntimeCorrelations(focusedExecution.value,diagnosticFocus.value,diagnosticFocusId.value);} function clearDiagnosticContext(){diagnosticTraceId.value="";diagnosticAuditId.value="";void router.replace({path:"/workflows/lifecycle",query:lifecycleQuery(focusedExecutionId.value||undefined)});} function openScheduledExecution(id?:string|null){if(!id)return;const e=executions.value.find(x=>x.id===id);if(e)return openRuntimeExecution(e);void router.push({path:"/runtime",query:{tab:"executions",source:"workflow-lifecycle",execution_id:id,...(selected.value?{workflow_id:selected.value.id}:{})}});}
function operatorErrorMessage(e:any,resource:"Execution"|"触发器",action?:string){const s=e?.response?.status;const d=String(e?.response?.data?.detail||e?.message||"");if(s===403)return `当前账号没有操作该${resource}的权限。`;if(s===409)return /Idempotency|幂等|replay|处理中|结果/i.test(d)?`${resource}${action?` ${action}`:""}发生幂等冲突或已有结果，请查看后端 Result Resource。`:`${resource}当前状态已变化，请刷新后重试。`;return `${resource}${action?` ${action}`:""}失败，请稍后重试。`;}
async function load(){loading.value=true;pageState.value="loading";error.value="";permissionDenied.value=false;try{workflows.value=(await workflowApi.list()).data;const requested=typeof route.query.workflow_id==="string"?route.query.workflow_id:"";if(requested&&workflows.value.some(x=>x.id===requested))selectedId.value=requested;else if(!selectedId.value||!workflows.value.some(x=>x.id===selectedId.value))selectedId.value=workflows.value[0]?.id||"";if(!workflows.value.length){selectedId.value="";pageState.value="empty";return;}if(selectedId.value)await loadDetails(selectedId.value);pageState.value="success";}catch(e:any){workflows.value=[];permissionDenied.value=e?.response?.status===403;error.value=permissionDenied.value?"":"工作流生命周期数据加载失败，请刷新后重试。";pageState.value=permissionDenied.value?"permission":"error";}finally{loading.value=false;}}
async function loadDetails(id:string){detailLoading.value=true;detailError.value="";try{const [v,t,e]=await Promise.all([workflowApi.versions(id),workflowApi.triggers(id),workflowApi.listExecutions(id)]);versions.value=v.data;triggers.value=t.data;executions.value=e.data;const er=await Promise.all(executions.value.map(async x=>[x.id,(await workflowApi.executionAvailability(x.id)).data.actions] as const));const tr=await Promise.all(triggers.value.map(async x=>[x.id,(await workflowApi.triggerAvailability(x.id)).data.actions] as const));executionAvailability.value=Object.fromEntries(er);triggerAvailability.value=Object.fromEntries(tr);const scheduled=triggers.value.filter(x=>x.trigger_type==="scheduled");const sr=await Promise.all(scheduled.map(async x=>[x.id,(await workflowApi.schedule(id,x.id)).data] as const));schedules.value=Object.fromEntries(sr);const requested=typeof route.query.execution_id==="string"?route.query.execution_id:"";if(requested&&executions.value.some(x=>x.id===requested))focusedExecutionId.value=requested;else if(!focusedExecutionId.value||!executions.value.some(x=>x.id===focusedExecutionId.value))focusedExecutionId.value=executions.value[0]?.id||"";}catch(e:any){versions.value=[];triggers.value=[];executions.value=[];schedules.value={};executionAvailability.value={};triggerAvailability.value={};permissionDenied.value=e?.response?.status===403;if(permissionDenied.value)detailError.value="当前账号没有读取工作流 Operator Action 可用性的权限。";else detailError.value="无法同步当前工作流的版本、触发器、运行数据或 Operator Action 可用性。请重试；若持续失败，请检查服务状态。";}finally{detailLoading.value=false;}}
async function selectWorkflow(id:string){selectedId.value=id;focusedExecutionId.value="";diagnosticTraceId.value="";diagnosticAuditId.value="";await loadDetails(id);} function handleStateAction(){if(pageState.value==="error"||pageState.value==="permission")void load();} function retryDetails(){if(selectedId.value)void loadDetails(selectedId.value);}
function requestInvoke(t:WorkflowTrigger){const a=triggerActionAvailability(t,"invoke");if(!a?.allowed){ElMessage.warning(`后端禁止当前 Trigger 执行：${a?.reason_code||"ACTION_NOT_AVAILABLE"}`);return;}invokeTarget.value=t;invokeDialogVisible.value=true;} function cancelInvoke(){if(invokeLoading.value)return;invokeDialogVisible.value=false;invokeTarget.value=null;}
async function confirmInvoke(){if(!selectedId.value||!invokeTarget.value||invokeLoading.value)return;const t=invokeTarget.value;const a=triggerActionAvailability(t,"invoke");if(!a?.allowed){ElMessage.warning(`后端已拒绝该操作：${a?.reason_code||"ACTION_NOT_AVAILABLE"}`);cancelInvoke();return;}invokeLoading.value=true;try{const r=await workflowApi.invokeTrigger(selectedId.value,t.id,{});ElMessage.success(`手动触发已提交，Result Resource ${r.data.id} 已返回；重复幂等请求由后端复用既有结果。`);invokeDialogVisible.value=false;invokeTarget.value=null;await loadDetails(selectedId.value);}catch(e:any){ElMessage.error(operatorErrorMessage(e,"触发器","invoke"));}finally{invokeLoading.value=false;}}
function requestExecutionAction(e:WorkflowExecution,a:ExecutionAction){if(executionActionLoading.value)return;const x=executionActionAvailability(e,a);if(!x?.allowed){ElMessage.warning(`后端禁止当前 Execution ${actionText[a]}：${x?.reason_code||"ACTION_NOT_ALLOWED"}`);return;}executionTarget.value=e;executionAction.value=a;executionDialogVisible.value=true;} function cancelExecutionAction(){if(executionActionLoading.value)return;executionDialogVisible.value=false;executionTarget.value=null;executionAction.value=null;}
async function confirmExecutionAction(){if(!executionTarget.value||!executionAction.value||executionActionLoading.value)return;const t=executionTarget.value,a=executionAction.value,x=executionActionAvailability(t,a);if(!x?.allowed){ElMessage.warning(`后端已拒绝该操作：${x?.reason_code||"ACTION_NOT_ALLOWED"}`);cancelExecutionAction();return;}executionActionLoading.value=true;try{let r;if(a==="run")r=await workflowApi.runExecution(t.id);else if(a==="cancel")r=await workflowApi.cancelExecution(t.id);else if(a==="retry")r=await workflowApi.retryExecution(t.id);else r=await workflowApi.resumeExecution(t.id);const result=r.data;const hint=a==="retry"?`Retry Result ${result.id}${result.retry_of_execution_id?`，来源 ${result.retry_of_execution_id}`:""}；相同幂等键由后端复用既有结果。`:a==="resume"?`Resume Result ${result.id}${result.resume_of_execution_id?`，来源 ${result.resume_of_execution_id}`:""}。`:`Result Resource ${result.id} 已返回。`;ElMessage.success(`Execution ${actionText[a]}已提交；${hint}`);executionDialogVisible.value=false;executionTarget.value=null;executionAction.value=null;await loadDetails(selectedId.value||t.workflow_id);}catch(e:any){ElMessage.error(operatorErrorMessage(e,"Execution",a));}finally{executionActionLoading.value=false;}}
function resetTriggerEditor(){triggerEditorVisible.value=false;triggerEditor.value={trigger:null,name:"",timezone:"UTC",interval_seconds:300,misfire_policy:"skip",catch_up_limit:10,event_id_field:"event_id",secret:""};} function openTriggerEditor(t:WorkflowTrigger){if(selected.value?.status==="archived")return;triggerEditor.value={trigger:t,name:t.name,timezone:(t.config as any)?.timezone||"UTC",interval_seconds:(t.config as any)?.interval_seconds||300,misfire_policy:(t.config as any)?.misfire_policy||"skip",catch_up_limit:(t.config as any)?.catch_up_limit||10,event_id_field:(t.config as any)?.event_id_field||"event_id",secret:""};triggerEditorVisible.value=true;} function cancelTriggerEditor(){if(triggerEditorLoading.value)return;resetTriggerEditor();}
async function saveTriggerEditor(){if(!selectedId.value||!triggerEditor.value.trigger||triggerEditorLoading.value)return;const t=triggerEditor.value.trigger;triggerEditorLoading.value=true;try{const payload=t.trigger_type==="scheduled"?{name:triggerEditor.value.name,config:{timezone:triggerEditor.value.timezone,interval_seconds:triggerEditor.value.interval_seconds,misfire_policy:triggerEditor.value.misfire_policy,catch_up_limit:triggerEditor.value.catch_up_limit}}:{name:triggerEditor.value.name,config:{auth_mode:"secret" as const,event_id_field:triggerEditor.value.event_id_field,...(triggerEditor.value.secret?{secret:triggerEditor.value.secret}:{})}};await workflowApi.updateTrigger(selectedId.value,t.id,payload);ElMessage.success("触发器配置已保存。已保留后端已存储的 Secret，不会回显敏感信息。");resetTriggerEditor();await loadDetails(selectedId.value);}catch(e:any){ElMessage.error(operatorErrorMessage(e,"触发器","保存"));}finally{triggerEditorLoading.value=false;}}
function requestDeleteTrigger(t:WorkflowTrigger){const a=triggerActionAvailability(t,"delete");if(!a?.allowed){ElMessage.warning(`后端禁止删除当前 Trigger：${a?.reason_code||"ACTION_NOT_AVAILABLE"}`);return;}deleteTriggerTarget.value=t;deleteTriggerDialogVisible.value=true;} function resetDeleteTrigger(){deleteTriggerDialogVisible.value=false;deleteTriggerTarget.value=null;} function cancelDeleteTrigger(){if(deleteTriggerLoading.value)return;resetDeleteTrigger();}
async function confirmDeleteTrigger(){if(!selectedId.value||!deleteTriggerTarget.value||deleteTriggerLoading.value)return;const t=deleteTriggerTarget.value,a=triggerActionAvailability(t,"delete");if(!a?.allowed){ElMessage.warning(`后端已拒绝该删除操作：${a?.reason_code||"ACTION_NOT_AVAILABLE"}`);cancelDeleteTrigger();return;}deleteTriggerLoading.value=true;try{await workflowApi.deleteTrigger(selectedId.value,t.id);ElMessage.success("触发器已删除。");resetDeleteTrigger();await loadDetails(selectedId.value);}catch(e:any){ElMessage.error(operatorErrorMessage(e,"触发器","删除"));}finally{deleteTriggerLoading.value=false;}}
function requestTriggerStatusAction(t:WorkflowTrigger,a:"enable"|"disable"){const x=triggerActionAvailability(t,a);if(!x?.allowed){ElMessage.warning(`后端禁止当前 Trigger ${a==="enable"?"启用":"停用"}：${x?.reason_code||"ACTION_NOT_AVAILABLE"}`);return;}triggerActionTarget.value=t;triggerAction.value=a;triggerActionDialogVisible.value=true;} function resetTriggerStatusAction(){triggerActionDialogVisible.value=false;triggerActionTarget.value=null;triggerAction.value=null;} function cancelTriggerStatusAction(){if(triggerActionLoading.value)return;resetTriggerStatusAction();}
async function confirmTriggerStatusAction(){if(!selectedId.value||!triggerActionTarget.value||!triggerAction.value||triggerActionLoading.value)return;const t=triggerActionTarget.value,a=triggerAction.value,x=triggerActionAvailability(t,a);if(!x?.allowed){ElMessage.warning(`后端已拒绝该操作：${x?.reason_code||"ACTION_NOT_AVAILABLE"}`);cancelTriggerStatusAction();return;}triggerActionLoading.value=true;try{if(a==="enable")await workflowApi.enableTrigger(selectedId.value,t.id);else await workflowApi.disableTrigger(selectedId.value,t.id);ElMessage.success(`触发器已${a==="enable"?"启用":"停用"}。`);resetTriggerStatusAction();await loadDetails(selectedId.value);}catch(e:any){ElMessage.error(operatorErrorMessage(e,"触发器",a==="enable"?"启用":"停用"));}finally{triggerActionLoading.value=false;}}
onMounted(()=>{void load();});
</script>

<template><div class="workflow-lifecycle-page"><PageHeader title="工作流生命周期" description="围绕 Workflow → Version → Trigger → Execution 建立真实后端状态与可观测操作链路。"/><StatePanel v-if="pageState !== 'success'" :state="pageState" :title="stateTitle" :description="stateDescription" action-label="重新加载" @action="handleStateAction"/><template v-else><SurfaceCard title="工作流" description="选择工作流查看版本、触发器、Execution 与诊断上下文。"><el-select v-model="selectedId" placeholder="选择工作流" style="width:100%;max-width:520px" @change="selectWorkflow"><el-option v-for="w in workflows" :key="w.id" :label="w.name" :value="w.id"/></el-select></SurfaceCard><SurfaceCard v-if="selected" title="生命周期" :description="selected.description || '工作流生命周期状态由后端真实资源驱动。'"><div class="lifecycle-steps"><div v-for="s in lifecycleSteps" :key="s.label" class="lifecycle-step" :class="{done:s.done,active:s.active}"><span class="step-dot"/><span>{{s.label}}</span></div></div></SurfaceCard><SurfaceCard title="版本" description="仅展示后端 Workflow Version 与发布状态。"><el-table v-if="versions.length" :data="versions" border><el-table-column prop="version" label="版本"/><el-table-column prop="status" label="状态"><template #default="{row}">{{displayStatus(row.status)}}</template></el-table-column><el-table-column prop="created_at" label="创建时间"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column></el-table><StatePanel v-else state="empty" title="暂无版本" description="当前工作流尚未创建版本。"/></SurfaceCard><SurfaceCard title="触发与调度" description="Trigger 配置写入与 Operator Action 均使用真实后端 Contract；Scheduler 目前仍保持只读"><el-table v-if="triggers.length" :data="triggers" border><el-table-column prop="name" label="触发器"/><el-table-column label="类型"><template #default="{row}">{{displayTriggerType(row.trigger_type)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{displayStatus(row.status)}}</template></el-table-column><el-table-column label="可用性"><template #default="{row}"><div class="availability-summary"><el-tag v-for="x in triggerAvailability[row.id] || []" :key="x.action">{{displayTriggerAction(x.action)}}：{{x.allowed?'可用':x.reason_code}}</el-tag></div></template></el-table-column><el-table-column label="最近 Execution"><template #default="{row}"><el-button v-if="schedules[row.id]?.last_execution_id" link @click="openScheduledExecution(schedules[row.id]?.last_execution_id)">{{schedules[row.id]?.last_execution_id}}</el-button><span v-else>-</span></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.trigger_type==='manual'" :disabled="!triggerActionAllowed(asTrigger(row),'invoke')" @click="requestInvoke(asTrigger(row))">立即运行</el-button><el-button v-if="row.status==='disabled'" :disabled="!triggerActionAllowed(asTrigger(row),'enable')" @click="requestTriggerStatusAction(asTrigger(row),'enable')">启用</el-button><el-button v-if="row.status==='enabled'" :disabled="!triggerActionAllowed(asTrigger(row),'disable')" @click="requestTriggerStatusAction(asTrigger(row),'disable')">停用</el-button><el-button v-if="row.trigger_type!=='manual'" :disabled="selected.status==='archived'" @click="openTriggerEditor(asTrigger(row))">编辑配置</el-button><el-button :disabled="selected.status==='archived'||!triggerActionAllowed(asTrigger(row),'delete')" @click="requestDeleteTrigger(asTrigger(row))">删除</el-button></template></el-table-column></el-table><StatePanel v-else state="empty" title="暂无触发器" description="发布工作流后可配置手动、定时或 Webhook 入口。"/></SurfaceCard><SurfaceCard title="Execution" description="运行操作严格消费后端 Operator Action Availability，不在前端复制状态机。"><el-table v-if="executions.length" :data="executions" border><el-table-column prop="id" label="Execution ID"/><el-table-column prop="status" label="状态"><template #default="{row}">{{displayStatus(row.status)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-for="a in executionActions(asExecution(row))" :key="a" @click="requestExecutionAction(asExecution(row),a)">{{actionText[a]}}</el-button><el-button @click="focusExecution(asExecution(row))">查看上下文</el-button><el-button @click="openRuntimeExecution(asExecution(row))">Runtime</el-button></template></el-table-column></el-table><StatePanel v-else state="empty" title="暂无 Execution" description="当前工作流尚无运行记录。"/></SurfaceCard><SurfaceCard v-if="focusedExecution" title="反向诊断上下文（Runtime 诊断）" :description="diagnosticFocus ? `${diagnosticFocusLabel}：${diagnosticFocusId}` : '选择 Trace/Audit 深链后可继续进入 Runtime Correlations。'"><div class="diagnostic-actions"><el-button v-if="diagnosticFocus" @click="continueDiagnostic">继续 {{diagnosticFocus === 'trace' ? 'Trace' : 'Audit'}} 诊断</el-button><el-button v-if="diagnosticFocus" @click="clearDiagnosticContext">清除诊断上下文</el-button><el-button @click="openRuntimeCorrelations(focusedExecution)">查看 Execution Correlations</el-button></div></SurfaceCard><StatePanel v-if="detailError" state="error" title="工作流详情加载失败" :description="detailError" action-label="重新加载详情" @action="retryDetails"/></template><ConfirmDialog v-model="invokeDialogVisible" title="确认立即运行" :loading="invokeLoading" confirm-text="确认运行" @confirm="confirmInvoke" @cancel="cancelInvoke"/><ConfirmDialog v-model="executionDialogVisible" :title="`确认${executionAction ? actionText[executionAction] : '操作'} Execution`" :loading="executionActionLoading" @confirm="confirmExecutionAction" @cancel="cancelExecutionAction"/><ConfirmDialog v-model="deleteTriggerDialogVisible" title="确认删除触发器" :loading="deleteTriggerLoading" @confirm="confirmDeleteTrigger" @cancel="cancelDeleteTrigger"/><ConfirmDialog v-model="triggerActionDialogVisible" :title="`确认${triggerAction === 'enable' ? '启用' : '停用'}触发器`" :loading="triggerActionLoading" @confirm="confirmTriggerStatusAction" @cancel="cancelTriggerStatusAction"/><el-dialog v-model="triggerEditorVisible" title="编辑触发器配置"><el-form><el-form-item label="名称"><el-input v-model="triggerEditor.name"/></el-form-item><template v-if="triggerEditor.trigger?.trigger_type==='scheduled'"><el-form-item label="时区"><el-input v-model="triggerEditor.timezone"/></el-form-item><el-form-item label="间隔秒数"><el-input-number v-model="triggerEditor.interval_seconds" :min="1"/></el-form-item><el-form-item label="错过策略"><el-select v-model="triggerEditor.misfire_policy"><el-option label="跳过" value="skip"/><el-option label="执行一次" value="fire_once"/><el-option label="追赶" value="catch_up"/></el-select></el-form-item><el-form-item label="追赶上限"><el-input-number v-model="triggerEditor.catch_up_limit" :min="1"/></el-form-item></template><template v-else><el-form-item label="事件 ID 字段"><el-input v-model="triggerEditor.event_id_field"/></el-form-item><el-form-item label="Secret"><el-input v-model="triggerEditor.secret" type="password"/></el-form-item></template></el-form><template #footer><el-button @click="cancelTriggerEditor">取消</el-button><el-button @click="saveTriggerEditor">保存</el-button></template></el-dialog></div></template>

<style scoped>.workflow-lifecycle-page{display:grid;gap:16px}.lifecycle-steps{display:flex;gap:18px;flex-wrap:wrap}.lifecycle-step{display:inline-flex;align-items:center;gap:8px;color:var(--el-text-color-secondary)}.lifecycle-step.done{color:var(--el-text-color-primary)}.lifecycle-step.active{font-weight:600}.step-dot{width:8px;height:8px;border-radius:50%;background:var(--el-border-color)}.lifecycle-step.done .step-dot{background:var(--el-color-success)}.lifecycle-step.active .step-dot{background:var(--el-color-primary)}.availability-summary{display:flex;gap:6px;flex-wrap:wrap}.diagnostic-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:900px){.workflow-lifecycle-page :deep(.el-table){font-size:12px}}</style>
